'use strict';
const $ = id => document.getElementById(id);
const money = cents => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(cents/100);
function confirmAction(message,label='Replace quote',title='Replace this quote?'){return new Promise(resolve=>{const dialog=$('confirm-dialog');$('confirm-title').textContent=title;$('confirm-accept').textContent=label;$('confirm-message').textContent=message;dialog.returnValue='cancel';dialog.addEventListener('close',()=>resolve(dialog.returnValue==='confirm'),{once:true});dialog.showModal();});}
const fields = ['business','email','client','number','issued','expires','discount','tax','notes'];
let nextId=3;
let items=[{id:1,description:'Website design & setup',quantity:1,rate:450},{id:2,description:'Monthly website maintenance',quantity:3,rate:50}];
const sample={business:'Bright Studio',email:'hello@example.com',client:'Sample client',number:'QT-001',discount:'0',tax:'0',notes:'Thank you for considering Bright Studio. Please get in touch to confirm the scope and timing before work begins.'};
const today=new Date();
const toDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
sample.issued=toDate(today); const expiry=new Date(today);expiry.setDate(expiry.getDate()+14);sample.expires=toDate(expiry);
$('issued').value=sample.issued;$('expires').value=sample.expires;
function safeNumber(v,max){const n=Number(v);return Number.isFinite(n)?Math.min(max,Math.max(0,n)):0;}
function lineTotal(item){return Math.round(Math.round(safeNumber(item.rate,1000000)*100)*safeNumber(item.quantity,10000));}
function calculate(){const subtotal=items.reduce((sum,item)=>sum+lineTotal(item),0);const discount=Math.round(subtotal*safeNumber($('discount').value,100)/100);const tax=Math.round((subtotal-discount)*safeNumber($('tax').value,100)/100);return {subtotal,discount,tax,total:subtotal-discount+tax};}
function text(id,value){$(id).textContent=value;}
function dateText(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value))return '—';const d=new Date(value+'T12:00:00');return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});}
function renderPreview(){
  for(const id of ['business','email','client','number'])text('p-'+id,$(id).value||({business:'Your business',client:'Your customer',number:'Quote number',email:''}[id]));
  for(const id of ['issued','expires'])text('p-'+id,dateText($(id).value));
  $('expires').setCustomValidity($('issued').value&&$('expires').value&&$('expires').value<$('issued').value?'Choose a date on or after the issue date.':'');
  const tbody=$('p-items');tbody.replaceChildren();
  for(const item of items){const tr=document.createElement('tr');for(const value of [item.description||'Untitled service',safeNumber(item.quantity,10000),money(Math.round(safeNumber(item.rate,1000000)*100)),money(lineTotal(item))]){const td=document.createElement('td');td.textContent=value;tr.append(td);}tbody.append(tr);const total=$('amount-'+item.id);if(total)total.textContent=money(lineTotal(item));}
  const totals=calculate();text('p-subtotal',money(totals.subtotal));text('p-discount','−'+money(totals.discount));text('p-tax',money(totals.tax));text('p-total',money(totals.total));text('discount-label',`Discount (${safeNumber($('discount').value,100)}%)`);text('tax-label',`Tax (${safeNumber($('tax').value,100)}%)`);text('p-notes',$('notes').value||''); if(window.accordReady)updateStudioSummary();
}
function renderItems(){
  $('items').replaceChildren();
  for(const item of items){
    const row=document.createElement('div');row.className='item';
    row.innerHTML='<div class="itemtop"><label>Service description<input maxlength="160" required></label><button type="button" class="remove" title="Remove service">×</button></div><div class="itemnumbers"><label>Quantity<input type="number" min="0.01" max="10000" step="0.01" required></label><label>Rate ($)<input type="number" min="0" max="1000000" step="0.01" required></label><div class="lineamount"><span>Amount</span><output></output></div></div>';
    const inputs=row.querySelectorAll('input');
    ['description','quantity','rate'].forEach((key,i)=>{inputs[i].value=item[key];inputs[i].id=`${key}-${item.id}`;inputs[i].addEventListener('input',()=>{item[key]=i===0?inputs[i].value:inputs[i].value;renderPreview();});});
    row.querySelector('output').id='amount-'+item.id;
    const remove=row.querySelector('button');remove.setAttribute('aria-label',`Remove service ${items.indexOf(item)+1}`);remove.addEventListener('click',()=>{if(items.length===1){text('status','Keep at least one service in your quote. You can edit its details.');return;}items=items.filter(x=>x.id!==item.id);renderItems();renderPreview();$('add').focus();text('status','Service removed. Your total has been updated.');});
    $('items').append(row);
  }
}
function addItem(data={description:'',quantity:1,rate:0}){if(items.length>=25)throw new Error('A quote can contain up to 25 services.');const item={id:nextId++,...data};items.push(item);renderItems();renderPreview();return item;}
$('add').addEventListener('click',()=>{try{const item=addItem();$('description-'+item.id).focus();text('status','New service added. Enter its description and price.');}catch(error){text('status',error.message);}});
for(const id of fields)$(id).addEventListener('input',renderPreview);
$('quote-form').addEventListener('submit',event=>event.preventDefault());
$('sample').addEventListener('click',async()=>{if(!await confirmAction('Replace your current quote with the example?'))return;for(const id of fields)$(id).value=sample[id];items=[{id:nextId++,description:'Website design & setup',quantity:1,rate:450},{id:nextId++,description:'Monthly website maintenance',quantity:3,rate:50}];renderItems();renderPreview();activeQuoteId=null;baseline=fingerprint();updateStudioSummary();text('status','Example loaded. Save it to keep a copy in your library.');});
$('print').addEventListener('click',()=>{if(!$('quote-form').reportValidity()){text('status','Please complete the highlighted fields before printing.');return;}renderPreview();text('status','Choose “Save as PDF” in the print window to keep your quote.');window.print();});
renderItems();renderPreview();
const libraryKey='accord-quotes-v1';
let library=[];
let activeQuoteId=null;
let baseline='';
let libraryReadable=true;
function snapshot(){return {version:1,fields:Object.fromEntries(fields.map(id=>[id,$(id).value])),items:items.map(({description,quantity,rate})=>({description,quantity,rate}))};}
function fingerprint(){return JSON.stringify(snapshot());}
function isDirty(){return baseline!==fingerprint();}
function validateDraft(draft){if(!draft||draft.version!==1||!draft.fields||!Array.isArray(draft.items)||draft.items.length<1||draft.items.length>25)throw new Error('Invalid draft');for(const field of fields){if(typeof draft.fields[field]!=='string'||draft.fields[field].length>2000)throw new Error('Invalid draft details');}for(const item of draft.items){if(!item||typeof item.description!=='string'||item.description.length>160||!['string','number'].includes(typeof item.quantity)||!['string','number'].includes(typeof item.rate)||!Number.isFinite(Number(item.quantity))||Number(item.quantity)<0||Number(item.quantity)>10000||!Number.isFinite(Number(item.rate))||Number(item.rate)<0||Number(item.rate)>1000000)throw new Error('Invalid service');}return draft;}
function totalFor(record){const subtotal=record.items.reduce((sum,item)=>sum+lineTotal(item),0);const discount=Math.round(subtotal*safeNumber(record.fields.discount,100)/100);return subtotal-discount+Math.round((subtotal-discount)*safeNumber(record.fields.tax,100)/100);}
function persistLibrary(next){if(!libraryReadable)throw new Error('The saved library could not be read. Existing data has been kept unchanged.');localStorage.setItem(libraryKey,JSON.stringify(next));library=next;renderLibrary();}
function updateStudioSummary(){text('summary-reference',$('number').value||'New quote');text('summary-total',money(calculate().total));text('summary-state',activeQuoteId?(isDirty()?'Unsaved changes':'Saved to library'):'Unsaved quote');text('nav-count',String(library.length));}
function switchView(view){const studio=view==='studio';$('studio-view').hidden=!studio;$('library-view').hidden=studio;for(const name of ['studio','library']){const button=$('nav-'+name);if(name===view)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}text('current-view',studio?'Quote studio':'Quote library');if(!studio)renderLibrary();window.scrollTo({top:0,behavior:'instant'});}
function loadIntoEditor(record,id){for(const field of fields)$(field).value=record.fields[field];items=record.items.map(item=>({...item,id:nextId++}));activeQuoteId=id;renderItems();baseline=fingerprint();renderPreview();updateStudioSummary();}
function nextReference(){let index=1;while(library.some(q=>q.fields.number===`AC-${String(index).padStart(3,'0')}`))index++;return `AC-${String(index).padStart(3,'0')}`;}
async function createQuote(){if(isDirty()&&!await confirmAction('Your current edits have not been saved. Start a new quote and discard these edits?','Start new quote','Unsaved changes'))return;const draft={version:1,fields:{...sample,business:$('business').value,email:$('email').value,client:'',number:nextReference(),notes:'Please confirm the scope and schedule before work begins.'},items:[{description:'',quantity:1,rate:0}]};loadIntoEditor(draft,null);switchView('studio');$('client').focus();text('status','New quote started. Add your client and services, then save it to the library.');}
function quoteCard(record){const card=document.createElement('article');card.className='quote-card';const details=document.createElement('div');const reference=document.createElement('div');reference.className='reference';reference.textContent=record.fields.number||'Untitled quote';const title=document.createElement('h2');title.textContent=record.fields.client||'Client not set';const subtitle=document.createElement('p');subtitle.textContent=(record.fields.business||'Business not set')+' · Updated '+new Date(record.updatedAt).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});details.append(reference,title,subtitle);const amount=document.createElement('div');amount.className='quote-value';amount.textContent=money(totalFor(record));const actions=document.createElement('div');actions.className='quote-actions';
 const button=(label,style,handler)=>{const b=document.createElement('button');b.type='button';b.className=style;b.textContent=label;b.setAttribute('aria-label',label+' '+(record.fields.number||'quote'));b.addEventListener('click',handler);actions.append(b);};
 button('Open','primary',async()=>{if(isDirty()&&!await confirmAction('Open this saved quote and discard the current unsaved edits?','Open quote','Unsaved changes'))return;loadIntoEditor(record,record.id);switchView('studio');text('status','Quote opened. Save quote will update this copy in your library.');});
 button('Duplicate','secondary',()=>{try{const copy=JSON.parse(JSON.stringify(record));copy.id=crypto.randomUUID();copy.fields.number=nextReference();copy.updatedAt=new Date().toISOString();persistLibrary([copy,...library]);text('library-status','Quote duplicated as '+copy.fields.number+'.');}catch(error){text('library-status','Could not duplicate this quote. '+error.message);}});
 button('Delete','secondary delete',async()=>{if(!await confirmAction('Remove '+(record.fields.number||'this quote')+' from the library? You can undo this deletion until your next library action.','Delete quote','Delete saved quote?'))return;try{persistLibrary(library.filter(q=>q.id!==record.id));if(activeQuoteId===record.id){activeQuoteId=null;updateStudioSummary();}const status=$('library-status');status.textContent='Quote removed. ';const undo=document.createElement('button');undo.className='secondary';undo.textContent='Undo delete';undo.addEventListener('click',()=>{try{if(!library.some(q=>q.id===record.id))persistLibrary([record,...library]);text('library-status','Quote restored.');}catch{ text('library-status','Unable to restore the quote. Browser storage may be full.');}});status.append(undo);}catch(error){text('library-status','Could not delete this quote. '+error.message);}});
 card.append(details,amount,actions);return card;}
function renderLibrary(){const query=$('quote-search').value.trim().toLowerCase();const sort=$('quote-sort').value;const found=library.filter(q=>[q.fields.client,q.fields.number,q.fields.business].join(' ').toLowerCase().includes(query));found.sort((a,b)=>sort==='value'?totalFor(b)-totalFor(a):sort==='client'?a.fields.client.localeCompare(b.fields.client):b.updatedAt.localeCompare(a.updatedAt));const target=$('library-results');target.replaceChildren();if(found.length===0){const empty=document.createElement('div');empty.className='empty-library';const heading=document.createElement('h2');heading.textContent=query?'No matching quotes':'Your next proposal starts here.';const p=document.createElement('p');p.textContent=query?'Try a different client name or quote reference.':'Save a quote from the studio to start your library.';empty.append(heading,p);target.append(empty);}else for(const record of found)target.append(quoteCard(record));text('nav-count',String(library.length));}
try{const raw=localStorage.getItem(libraryKey);if(raw){const parsed=JSON.parse(raw);if(!Array.isArray(parsed))throw new Error('Invalid library');const ids=new Set();for(const record of parsed){validateDraft(record);if(typeof record.id!=='string'||ids.has(record.id)||typeof record.updatedAt!=='string'||!Number.isFinite(Date.parse(record.updatedAt)))throw new Error('Invalid saved quote');ids.add(record.id);}library=parsed;}}catch{libraryReadable=false;text('status','Saved quotes could not be read. Existing browser data has been kept unchanged.');}
$('save-draft').addEventListener('click',()=>{if(!$('quote-form').reportValidity()){text('status','Complete the highlighted fields before saving this quote.');return;}try{const draft=validateDraft(snapshot());const record={...draft,id:activeQuoteId||crypto.randomUUID(),updatedAt:new Date().toISOString()};persistLibrary([record,...library.filter(q=>q.id!==record.id)]);activeQuoteId=record.id;baseline=fingerprint();updateStudioSummary();text('status','Quote saved to your library on this device.');}catch(error){text('status','Unable to save. '+error.message);}});
$('nav-studio').addEventListener('click',()=>switchView('studio'));$('nav-library').addEventListener('click',()=>switchView('library'));$('new-quote').addEventListener('click',createQuote);$('library-new').addEventListener('click',createQuote);$('quote-search').addEventListener('input',renderLibrary);$('quote-sort').addEventListener('change',renderLibrary);
const oldKey='quotable-draft-v1';try{$('load-draft').hidden=!localStorage.getItem(oldKey);}catch{$('load-draft').hidden=true;}
$('load-draft').addEventListener('click',async()=>{try{const raw=localStorage.getItem(oldKey);if(!raw){text('status','No earlier draft was found.');return;}const draft=validateDraft(JSON.parse(raw));if(isDirty()&&!await confirmAction('Replace your current edits with the draft saved in the earlier app?','Load earlier draft','Unsaved changes'))return;loadIntoEditor(draft,null);text('status','Earlier draft loaded. Select Save quote to add it to your new library.');}catch{text('status','The earlier draft could not be loaded. Your current quote has not changed.');}});
baseline=fingerprint();window.accordReady=true;renderLibrary();updateStudioSummary();
window.addEventListener('beforeunload',event=>{if(isDirty()){event.preventDefault();event.returnValue='';}});

const context=document.modelContext;
if(context?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
register({name:'read_quote',title:'Read the current quote',description:'Read the visible draft quote and calculated USD totals in cents.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(){return {business:$('business').value,client:$('client').value,services:items.map(({description,quantity,rate})=>({description,quantity,rate})),totals:calculate()};}});
register({name:'add_quote_service',title:'Add a service to the draft',description:'Add a service to the currently visible quote draft and recalculate its totals. Does not send or print the quote.',inputSchema:{type:'object',properties:{description:{type:'string',minLength:1,maxLength:160},quantity:{type:'number',minimum:0.01,maximum:10000},rate:{type:'number',minimum:0,maximum:1000000}},required:['description','quantity','rate'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input.description!=='string'||!input.description.trim()||input.description.length>160||!Number.isFinite(input.quantity)||input.quantity<0.01||input.quantity>10000||!Number.isFinite(input.rate)||input.rate<0||input.rate>1000000||Object.keys(input).some(k=>!['description','quantity','rate'].includes(k)))throw new Error('Provide a description, a quantity from 0.01 to 10000, and a rate from 0 to 1000000.');addItem({description:input.description,quantity:input.quantity,rate:input.rate});return {serviceCount:items.length,totals:calculate()};}});
window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
